/// Omnislice. Cost 0, Enemy. Deal damage (`max(current_damage, 8)`
/// matching pin's `base_damage or effect_vars.damage(=8)` fallback) to
/// the target, then splash the same damage value to every other alive
/// enemy. Mirrors `sts2_env/cards/colorless.py::omnislice` at pin
/// `01c094d` (`apply_damage(target, base_damage or 8); splash =
/// result.blocked + result.unblocked_damage; for teammate in
/// get_teammates_of(target): apply_damage(teammate, splash,
/// UNPOWERED|MOVE)`). The Rust simplification uses the pre-block
/// damage value as the splash multiplier — matches Python when the
/// primary hit lands fully (no block on target). Bead `sts2-rs-6ynt.8`
/// wave (Omnislice).
pub(crate) fn play_omnislice(state: &mut CombatState, target: Option<CreatureUid>) -> EffectResult {
    let t = target.expect("Omnislice: Enemy-targeted");
    // C# `Omnislice` is `DamageVar(8m, Move)` (upgrade +3 → 11). The spec
    // now carries the faithful base (8/11), so `current_damage` already
    // yields it — no `max(.,8)` floor needed. Keeping the spec base correct
    // also lets Thrash's exhaust-fold (`Thrash.OnPlay` reads the exhausted
    // attack's `Damage.BaseValue`) see Omnislice's 8 instead of a stub 0.
    // Bead `sts2-rs-266ml`.
    let dmg = current_damage(state);
    // C# `Omnislice.OnPlay` splashes the PRIMARY hit's `TotalDamage +
    // OverkillDamage` (its realized, post-block, overkill-inclusive damage)
    // — NOT the nominal card damage. Capture the primary outcome's
    // `total_damage` (== unclamped post-block incl. overkill) for the splash
    // amount below. The prior port splashed the raw `dmg`, diverging whenever
    // the primary's realized damage differed (block / Vulnerable / overkill);
    // surfaced as ~56 fuzz-seed MONSTER_STATE|OMNISLICE divergences. Bead
    // `sts2-rs-0bpvs`.
    let primary = deal_damage_player_to_enemy_full(state, t, dmg);
    // C# splashes `damageResult.TotalDamage + damageResult.OverkillDamage`
    // (`Omnislice.cs:41`) — realized post-block damage PLUS the overkill
    // beyond the target's remaining HP. The prior port dropped `+ overkill`,
    // so a primary that over-killed a low-HP enemy splashed only the clamped
    // `TotalDamage` (fuzz seed 1208: an 11-HP slime took a 21-damage primary →
    // splash should be 21, not 11; teammates diverged by exactly the overkill).
    let splash_amount = primary.total_damage + primary.overkill;
    let other_enemies: SmallVec<[CreatureUid; 8]> = state
        .enemy_uids
        .iter()
        .copied()
        .filter(|u| u.0 != t.0)
        .filter(|u| {
            state
                .creatures
                .iter()
                .any(|c| c.id == u.0 && c.current_hp > 0)
        })
        .collect();
    // The splash is ONE multi-target `CreatureCmd.Damage(list2, ..)`
    // (Omnislice.cs:41): every teammate loses its HP before
    // `Kill(killedCreatures)`, so when the splash fells the last enemies their
    // `AfterDeath` (Gremlin Horn's energy + draw) runs with the combat already
    // ending. Killing each as it was hit let the first one's Gremlin Horn draw
    // (random-loadout Regent v0.107.1 8183).
    sts2_core::damage::with_deferred_enemy_deaths(state, |state| {
        for e in other_enemies {
            // C# `Omnislice.cs:41` deals splash damage with
            // `ValueProp.Unpowered | ValueProp.Move`, so powered effects (e.g.
            // Miniature Cannon) do NOT apply to splash hits — only the primary
            // hit. `deal_damage_player_to_enemy` hardcodes `MOVE` (powered), so
            // we route splash through `apply_damage` with the Unpowered flag and
            // the primary's realized `splash_amount` (see capture above).
            // Bead `sts2-rs-0bpvs`.
            let splash_props =
                sts2_core::hooks::ValueProps::MOVE.union(sts2_core::hooks::ValueProps::UNPOWERED);
            let _ = sts2_core::damage::apply_damage(
                state,
                sts2_core::hooks::CreatureRef::Player,
                e,
                splash_amount,
                splash_props,
                Some(CardId::Omnislice),
            );
        }
    });
    EffectResult::Resolved
}

